INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63200744', 63200744, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI KEKARANTINAAN KESEHATAN KELAS I TANJUNG PINANG', 'Masker Gas', 'Barang', 'E-Purchasing', 'Kepulauan Riau, Tanjung Pinang (Kota)', 15798000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '( 2, UNIT, @ 7899000 )', '1. Masker Gas ( 2, UNIT, @ 7899000 );', 'Pekerjaan ini meliputi penyediaan alat pelindung diri (APD) berupa masker gas atau respirator yang dirancang khusus untuk melindungi pernapasan petugas dari paparan uap kimia, gas berbahaya, dan partikel halus selama pelaksanaan tugas lapangan di lingkungan Balai Kekarantinaan Kesehatan (BKK). Ruang lingkup pengadaan mencakup penyediaan unit masker yang menutupi area hidung dan mulut secara kedap, dilengkapi dengan sistem filter atau katrid yang dapat diganti sesuai dengan jenis ancaman polutan yang dihadapi (seperti pada kegiatan fumigasi atau penyemprotan insektisida). Spesifikasi teknis ditekankan pada penggunaan material yang ringan, elastis, dan nyaman digunakan dalam jangka waktu lama, serta memiliki segel yang kuat untuk mencegah kebocoran udara dari samping. Pengadaan ini bertujuan untuk menjamin keselamatan dan kesehatan kerja (K3) bagi petugas saat melakukan intervensi pengendalian faktor risiko penyakit, guna memitigasi risiko keracunan atau gangguan pernapasan akibat paparan bahan kimia berbahaya sepanjang tahun anggaran 2026.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 778541);
