INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63200988', 63200988, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI KEKARANTINAAN KESEHATAN KELAS I TANJUNG PINANG', 'Belanja Bahan Pelaksanaan Survei Faktor Risiko Penyakit DBD', 'Barang', 'Pengadaan Langsung', 'Kepulauan Riau, Tanjung Pinang (Kota)', 720000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', '1. ATK 1 PT x 1 KL ( 36, PT, @ 20000 );', 'Pekerjaan ini meliputi penyediaan sarana Alat Tulis Kantor (ATK) dan bahan pendukung administrasi lapangan yang diperlukan untuk menunjang kegiatan surveilans serta pendataan faktor risiko penyakit Demam Berdarah Dengue (DBD) di wilayah kerja Balai Kekarantinaan Kesehatan (BKK). Ruang lingkup pengadaan mencakup penyediaan kertas formulir pencatatan jentik, alat tulis permanen untuk pelabelan sampel, map plastik pelindung dokumen lapangan agar tidak rusak terkena air, serta buku catatan harian petugas survei. Spesifikasi barang ditekankan pada kualitas fungsi yang standar guna menjamin keakuratan dokumentasi data hasil pemeriksaan jentik (House Index) di lapangan. Pengadaan ini bertujuan untuk memastikan ketersediaan logistik pencatatan yang memadai, sehingga seluruh data surveilans dapat terinventarisasi dengan baik, rapi, dan sistematis sebagai dasar pengambilan kebijakan pengendalian vektor DBD sepanjang tahun anggaran 2026.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 778690);
