INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63201195', 63201195, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI KEKARANTINAAN KESEHATAN KELAS I TANJUNG PINANG', 'Box Arsip', 'Barang', 'E-Purchasing', 'Kepulauan Riau, Tanjung Pinang (Kota)', 11400000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '( 190, BOX, @ 60000 )', '1. Box Arsip ( 190, BOX, @ 60000 );', 'Pekerjaan ini meliputi penyediaan sarana penyimpanan dokumen berupa box arsip berkualitas standar untuk menata dan mengamankan berkas administrasi maupun dokumen teknis di lingkungan Balai Kekarantinaan Kesehatan (BKK). Ruang lingkup pengadaan mencakup penyediaan box arsip dengan bahan karton kokoh atau plastik yang tahan lama, dilengkapi dengan kolom pelabelan yang jelas untuk memudahkan identifikasi isi dokumen. Spesifikasi barang ditekankan pada kekuatan konstruksi box agar mampu menahan beban tumpukan berkas dan melindungi dokumen dari debu, kelembapan, serta kerusakan fisik lainnya selama masa penyimpanan di gudang atau ruang arsip. Pengadaan ini bertujuan untuk mewujudkan tata kelola kearsipan yang rapi, sistematis, dan mudah diakses kembali saat dibutuhkan (retrieval), guna mendukung tertib administrasi serta efisiensi ruang kerja sepanjang tahun anggaran 2026', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 778850);
