INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63201103', 63201103, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI KEKARANTINAAN KESEHATAN KELAS I TANJUNG PINANG', 'Belanja Bahan Penyusunan Rencana Kontijensi Penanggulangan KKMMD di Wilayah Kerja Ranai', 'Barang', 'Pengadaan Langsung', 'Kepulauan Riau, Tanjung Pinang (Kota)', 750000, 'May 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', '1. ATK dan Penggandaan Materi ( 1, PT, @ 500000 ); 2. Spanduk ( 1, PT, @ 250000 );', 'Pekerjaan ini meliputi penyediaan sarana Alat Tulis Kantor (ATK) dan media informasi berupa spanduk yang diperlukan untuk mendukung kelancaran rangkaian kegiatan penyusunan dokumen Rencana Kontijensi Penanggulangan KKMMD di wilayah kerja Ranai. Ruang lingkup pengadaan mencakup penyediaan logistik administrasi seperti kertas, alat tulis, map folder, dan penggandaan draf dokumen, serta pembuatan spanduk sebagai alat sosialisasi dan identitas kegiatan di lokasi pertemuan. Spesifikasi teknis mengharuskan penggunaan bahan cetak yang berkualitas, tulisan yang jelas dan mudah dibaca, serta materi ATK yang fungsional guna mendukung proses diskusi, pencatatan, dan finalisasi rencana kerja secara sistematis. Pengadaan ini bertujuan untuk menjamin ketersediaan bahan pendukung yang memadai bagi tim penyusun, sehingga dokumen teknis penanggulangan kedaruratan kesehatan dapat tersusun secara rapi, tepat waktu, dan terdokumentasi dengan baik sesuai standar operasional prosedur yang ditetapkan sepanjang tahun anggaran 2026.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 779708);
