INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63201133', 63201133, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI KEKARANTINAAN KESEHATAN KELAS I TANJUNG PINANG', 'Pemusnahan Limbah Medis', 'Jasa Lainnya', 'Pengadaan Langsung', 'Kepulauan Riau, Tanjung Pinang (Kota)', 8400000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '( 150, PT, @ 56000 )', '1. Pemusnahan Limbah Medis ( 150, PT, @ 56000 );', 'Pekerjaan ini meliputi jasa pengangkutan, pengolahan, dan pemusnahan limbah medis kategori infeksius yang dihasilkan dari kegiatan operasional klinis, laboratorium, serta pengawasan kesehatan di lingkungan Balai Kekarantinaan Kesehatan (BKK). Ruang lingkup pekerjaan mencakup pengambilan limbah dari tempat penampungan sementara (TPS) , proses pengangkutan sesuai prosedur keamanan bahan berbahaya dan beracun (B3), hingga pemusnahan akhir menggunakan fasilitas insinerator atau teknologi pemusnah yang memiliki izin resmi dari kementerian terkait. Spesifikasi teknis mewajibkan penyedia jasa memiliki lisensi serta sertifikasi pengolahan limbah yang sah serta wajib menyerahkan bukti manifest (dokumen limbah) yang akuntabel sebagai bukti bahwa limbah telah dimusnahkan sesuai standar perlindungan lingkungan. Pengadaan ini bertujuan untuk mencegah terjadinya pencemaran lingkungan serta risiko penularan penyakit di masyarakat, guna menjamin terciptanya lingkungan kerja yang bersih, sehat, dan sesuai dengan ketentuan hukum yang berlaku sepanjang tahun anggaran 2026.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 779796);
