INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63201060', 63201060, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI KEKARANTINAAN KESEHATAN KELAS I TANJUNG PINANG', 'Identifikasi Tikus dan Pinjal', 'Barang', 'Pengadaan Langsung', 'Kepulauan Riau, Tanjung Pinang (Kota)', 360000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', '1. Belanja Bahan;', 'Pekerjaan ini meliputi penyediaan sarana administrasi dan bahan kimia teknis yang diperlukan untuk proses identifikasi spesies tikus serta koleksi ektoparasit (pinjal) di laboratorium atau pos lapangan Balai Kekarantinaan Kesehatan (BKK). Ruang lingkup pengadaan mencakup penyediaan Formulir Identifikasi (berupa lembar pencatatan data morfometrik tikus, indeks pinjal, dan koordinat lokasi) menggunakan kertas berkualitas yang tidak mudah robek, serta penyediaan Alkohol (Etanol) dengan konsentrasi 70-96% standar laboratorium sebagai bahan fiksasi dan pengawet spesimen pinjal agar struktur tubuhnya tidak rusak sebelum diidentifikasi di bawah mikroskop. Spesifikasi teknis mengharuskan alkohol dikemas dalam wadah yang rapat untuk mencegah penguapan, sementara formulir harus dicetak dengan layout yang presisi guna memudahkan petugas dalam melakukan tabulasi data surveilans zoonosis. Pengadaan ini bertujuan untuk menjamin ketersediaan logistik pendukung yang standar demi akurasi pendataan dan kelestarian sampel spesimen dalam rangka pemantauan risiko penyakit Pes dan Leptospirosis sepanjang tahun anggaran 2026.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 779907);
